const input = $input.first().json;
const event = input.body ?? input;
for (const key of ['specversion', 'id', 'source', 'type']) {
  if (!event[key]) throw new Error(`missing CloudEvent field: ${key}`);
}
if (event.specversion !== '1.0') throw new Error(`unsupported CloudEvents specversion: ${event.specversion}`);
return [{ json: {
  specversion: '1.0',
  id: `${event.id}:n8n-forward`,
  source: 'urn:ordivon:integration:n8n',
  type: 'io.ordivon.integration.smoke.forward.v1',
  subject: event.subject ?? 'integration-smoke',
  time: new Date().toISOString(),
  datacontenttype: 'application/json',
  correlationid: event.id,
  data: {
    requestType: event.type,
    requestSource: event.source,
    payload: event.data ?? null
  }
} }];

const echo = $input.first().json;
const forwarded = echo.json ?? {};
if (!forwarded.correlationid) throw new Error('external echo did not preserve correlationid');
return [{ json: {
  specversion: '1.0',
  id: `${forwarded.correlationid}:n8n-result`,
  source: 'urn:ordivon:integration:n8n',
  type: 'io.ordivon.integration.result.v1',
  subject: forwarded.correlationid,
  time: new Date().toISOString(),
  datacontenttype: 'application/json',
  correlationid: forwarded.correlationid,
  data: {
    provider: 'n8n',
    externalService: 'httpbin.org',
    externalMethod: 'POST',
    echoedType: forwarded.type,
    echoedPayload: forwarded.data
  }
} }];
